import { composeStories } from "@storybook/react";
import {
  fireEvent,
  render,
  screen,
  waitFor,
  waitForElementToBeRemoved,
} from "@testing-library/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import Collapsible from "../Collapsible";
import Accordion from "./Accordion";
import * as stories from "./Accordion.stories";

const { Default } = composeStories(stories) as any;

// tests helper functions
const helper = {
  expectHeader: (name: string | RegExp, expected: boolean) => {
    if (expected)
      expect(screen.getByRole("button", { name })).toBeInTheDocument();
    else expect(screen.queryByRole("button", { name })).not.toBeInTheDocument();
  },
  expectPanel: (name: string | RegExp, expected: boolean) => {
    if (expected)
      expect(screen.getByRole("region", { name })).toBeInTheDocument();
    else expect(screen.queryByRole("region", { name })).not.toBeInTheDocument();
  },
  getHeader: (name: string | RegExp) => screen.getByRole("button", { name }),
};

describe("Accordion component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Default />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("display warnings with invalid props", () => {
    render(
      // @ts-expect-error
      <Accordion index="1">
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(
      /Accordion expects `index` and `defaultIndex` to be arrays/
    );

    render(
      <Accordion single index={[1]}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    expect(consoleSpy.warn).toHaveBeenCalledTimes(2);
    expect(consoleSpy.warn.mock.calls[1][0]).toMatch(
      /Accordion expects `index` and `defaultIndex` to be numbers/
    );
  });

  it("passes through props", () => {
    render(
      <Accordion data-testid="accordion">
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    expect(screen.getByTestId("accordion")).toBeTruthy();
  });

  it("Allows conditionnal rendering of children", () => {
    render(
      <Accordion>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        {false && (
          <Collapsible title="Title 2">Content of section 2</Collapsible>
        )}
      </Accordion>
    );
    helper.expectHeader(/Title 1/, true);
    helper.expectHeader(/Title 2/, false);
  });

  it("expand all items by default", async () => {
    const onChange = jest.fn();
    render(
      <Accordion onChange={onChange}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    const button1 = helper.getHeader(/Title 1/);
    const button2 = helper.getHeader(/Title 2/);
    helper.expectPanel(/Title 1/, false);

    // expand section 1
    fireEvent.click(button1);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([0]);
    helper.expectPanel(/Title 1/, true);

    // collapse section 1
    fireEvent.click(button1);
    expect(onChange).toHaveBeenCalledTimes(2);
    await waitForElementToBeRemoved(
      screen.queryByRole("region", { name: /Title 1/ })
    ).then(() => helper.expectPanel(/Title 1/, false));

    // expand section 1 & 2
    fireEvent.click(button1);
    fireEvent.click(button2);
    expect(onChange).toHaveBeenCalledTimes(4);
    expect(onChange).toHaveBeenLastCalledWith([0, 1]);
    await waitFor(() => {
      helper.expectPanel(/Title 1/, true);
      helper.expectPanel(/Title 2/, true);
    });
  });

  it("expand one item only in single mode", async () => {
    const onChange = jest.fn();
    render(
      <Accordion onChange={onChange} single defaultIndex={1}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    const button1 = helper.getHeader(/Title 1/);
    fireEvent.click(button1);
    helper.expectPanel(/Title 1/, true);
    await waitForElementToBeRemoved(
      screen.queryByRole("region", { name: /Title 2/ })
    ).then(() => helper.expectPanel(/Title 2/, false));
  });

  it("collapse/unfold all items at once", async () => {
    const onChange = jest.fn();
    render(
      <Accordion onChange={onChange}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );

    const unfoldAllButton = screen.getByRole("button", { name: /Unfold all/ });
    const collapseAllButton = screen.getByRole("button", { name: /Collapse all/ });
    fireEvent.click(unfoldAllButton);
    helper.expectPanel(/Title 1/, true);
    helper.expectPanel(/Title 2/, true);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([0, 1]);

    fireEvent.click(collapseAllButton);
    await waitForElementToBeRemoved(
      screen.queryByRole("region", { name: /Title 1/ })
    ).then(() => {
      helper.expectPanel(/Title 1/, false);
      helper.expectPanel(/Title 2/, false);
    });
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith([]);
  });

  it("allows renaming of bulk action buttons", () => {
    render(
      <Accordion collapseAllLabel="Custom Label1" unfoldAllLabel="Custom Label2">
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    expect(
      screen.getByRole("button", { name: /Custom Label1/ })
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: /Custom Label2/ })
    ).toBeInTheDocument();
  });

  it("allow switching from multi to single mode", async () => {
    const onChange = jest.fn();
    const { rerender } = render(
      <Accordion onChange={onChange}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );

    // unfold all
    const unfoldAllButton = screen.getByRole("button", { name: /Unfold all/ });
    fireEvent.click(unfoldAllButton);
    helper.expectPanel(/Title 1/, true);
    helper.expectPanel(/Title 2/, true);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith([0, 1]);

    // switch to single mode
    rerender(
      <Accordion single onChange={onChange}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );

    // switching to single mode should keep only first item opened
    helper.expectPanel(/Title 1/, true);

    // open section 2 > should close section 1
    const button2 = helper.getHeader(/Title 2/);
    fireEvent.click(button2);
    await waitForElementToBeRemoved(
      screen.queryByRole("region", { name: /Title 1/ })
    ).then(() =>
      helper.expectPanel(/Title 1/, false)
    );
    helper.expectPanel(/Title 2/, true);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith(1);
  });

  it("allow switching from single to multi mode", async () => {
    const onChange = jest.fn();
    const { rerender } = render(
      <Accordion single onChange={onChange}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );

    // open section 1
    const button1 = helper.getHeader(/Title 1/);
    const button2 = helper.getHeader(/Title 2/);
    fireEvent.click(button1);
    helper.expectPanel(/Title 1/, true);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenLastCalledWith(0);
    
    // switch to multi mode
    rerender(
      <Accordion onChange={onChange}>
        <Collapsible title="Title 1">Content of section 1</Collapsible>
        <Collapsible title="Title 2">Content of section 2</Collapsible>
      </Accordion>
    );
    fireEvent.click(button2);
    helper.expectPanel(/Title 1/, true);
    helper.expectPanel(/Title 2/, true);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenLastCalledWith([0, 1]);
  });
});
